        "jsd": [0.169964, 0.129382, 0.107086, 0.064225]
    }
}

transitions = ["0→1", "1→2", "2→3", "3→4", "4→5"]
x = np.arange(len(transitions))

# Colors by model
model_colors = {
    "Llama-8B": "#E63946",
    "Qwen-1.5B": "#457B9D",
    "Qwen-7B": "#1D3557",
    "Mistral-7B": "#2A9D8F",
    "Pythia-1.4B": "#E9C46A",
    "OLMo": "#F4A261",
}

# Linestyle by domain
domain_styles = {
    "C4": "-",
    "arXiv": "--",
    "Wikipedia": ":",
}

